import{c as i,Q as a,j as e,m as t}from"./chunks/framework.DoOjWOm2.js";const c=JSON.parse('{"title":"Share Libraries with Friends and Family","description":"","frontmatter":{},"headers":[],"relativePath":"hub/share-with-friends.md","filePath":"hub/share-with-friends.md"}'),n={name:"hub/share-with-friends.md"};function r(h,s,l,o,p,d){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="share-libraries-with-friends-and-family" tabindex="-1">Share Libraries with Friends and Family <a class="header-anchor" href="#share-libraries-with-friends-and-family" aria-label="Permalink to &quot;Share Libraries with Friends and Family&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Hub sharing lets you grant access to your media library to friends and family through the hub. Go to your server&#39;s <strong>Sharing</strong> tab → choose what to share → invite by email or link. Recipients see your server under <strong>&quot;Shared with me&quot;</strong> in their hub dashboard without needing to install anything or be on the same network. Permissions are configurable from view-only to full playback with optional download access.</p><hr><h2 id="_1-how-hub-sharing-works" tabindex="-1">1. How Hub Sharing Works <a class="header-anchor" href="#_1-how-hub-sharing-works" aria-label="Permalink to &quot;1. How Hub Sharing Works&quot;">​</a></h2><p>The sharing model is simple:</p><ul><li><strong>You</strong> (library owner) grant access from the hub dashboard</li><li><strong>Your friend</strong> receives an invite by email or a shareable link</li><li><strong>Your friend</strong> logs into the hub and sees your server under <strong>&quot;Shared with me&quot;</strong></li><li><strong>You</strong> retain full control — revoke or change permissions at any time</li></ul><h3 id="three-sharing-scopes" tabindex="-1">Three sharing scopes <a class="header-anchor" href="#three-sharing-scopes" aria-label="Permalink to &quot;Three sharing scopes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scope</th><th>What the recipient sees</th></tr></thead><tbody><tr><td>Entire library</td><td>All items in the selected library</td></tr><tr><td>Specific folders</td><td>Only the folders you chose (e.g., <code>Movies/Classics</code>)</td></tr><tr><td>Specific media items</td><td>Only the individual items you selected</td></tr></tbody></table><h3 id="three-permission-levels" tabindex="-1">Three permission levels <a class="header-anchor" href="#three-permission-levels" aria-label="Permalink to &quot;Three permission levels&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Permission</th><th>Browse</th><th>Play</th><th>Cast / DLNA</th><th>Download</th></tr></thead><tbody><tr><td><strong>View only</strong></td><td>✅</td><td>❌</td><td>❌</td><td>❌</td></tr><tr><td><strong>View + Playback</strong></td><td>✅</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td><strong>View + Playback + Download</strong></td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr></tbody></table><blockquote><p><strong>Note:</strong> DLNA casting requires the <code>View + Playback + Download</code> permission — the download component enables the stream to be redirected to a DLNA renderer.</p></blockquote><hr><h2 id="_2-granting-access-via-the-hub-dashboard" tabindex="-1">2. Granting Access via the Hub Dashboard <a class="header-anchor" href="#_2-granting-access-via-the-hub-dashboard" aria-label="Permalink to &quot;2. Granting Access via the Hub Dashboard&quot;">​</a></h2><ol><li>Log into the hub at <code>https://hub.phlix.app</code> (or your self-hosted hub URL)</li><li>Navigate to <strong>Servers</strong> → your server → <strong>Sharing</strong> tab</li><li>Click <strong>Share Library</strong></li><li>Choose what to share (entire library, specific folders, or specific items)</li><li>Select the permission level: <strong>View only</strong> / <strong>View + Playback</strong> / <strong>View + Playback + Download</strong></li><li>Choose invite method: <ul><li><strong>Email</strong> — enter the recipient&#39;s address; optionally set an expiry date</li><li><strong>Shareable link</strong> — generates a direct link anyone can use</li></ul></li><li>Click <strong>Send Invite</strong></li></ol><h3 id="per-profile-sharing-content-filtering" tabindex="-1">Per-profile sharing (content filtering) <a class="header-anchor" href="#per-profile-sharing-content-filtering" aria-label="Permalink to &quot;Per-profile sharing (content filtering)&quot;">​</a></h3><p>You can restrict shared content to G-rated media for certain recipients. This uses the same rating filter system as user profiles. When granting access, enable <strong>&quot;Restrict to G-rated content&quot;</strong> — the recipient will only see media approved for general audiences in that shared library, regardless of the actual library contents.</p><hr><h2 id="_3-granting-access-via-cli" tabindex="-1">3. Granting Access via CLI <a class="header-anchor" href="#_3-granting-access-via-cli" aria-label="Permalink to &quot;3. Granting Access via CLI&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Grant view-only access to a friend&#39;s account</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> share:grant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> friend@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --library</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Movies&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --permission</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Grant view+playback access</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> share:grant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> friend@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --library</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Movies&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --permission</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playback</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Grant view+playback+download access (full access — enables DLNA casting)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> share:grant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> friend@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --library</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Movies&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --permission</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Share a specific folder instead of the whole library</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> share:grant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> friend@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --folder</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Movies/Classics&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --permission</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playback</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Share a specific media item by its ID</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> share:grant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> friend@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --item</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;abc123-def456&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --permission</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># List all active shares for a user</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> share:list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> friend@example.com</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Revoke a friend&#39;s access to a library</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> share:revoke</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> friend@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --library</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Movies&quot;</span></span></code></pre></div><hr><h2 id="_4-accepting-a-share-invite" tabindex="-1">4. Accepting a Share Invite <a class="header-anchor" href="#_4-accepting-a-share-invite" aria-label="Permalink to &quot;4. Accepting a Share Invite&quot;">​</a></h2><h3 id="via-email-invite" tabindex="-1">Via email invite <a class="header-anchor" href="#via-email-invite" aria-label="Permalink to &quot;Via email invite&quot;">​</a></h3><ol><li>Open the invite email (check <strong>spam</strong> if it doesn&#39;t arrive within a few minutes)</li><li>Click <strong>Accept Invite</strong> — if you don&#39;t have a hub account yet, create one first</li><li>Log into the hub — the shared server appears under <strong>&quot;Shared with me&quot;</strong> in your dashboard</li><li>Select the shared server to browse and play the library</li></ol><h3 id="via-shareable-link" tabindex="-1">Via shareable link <a class="header-anchor" href="#via-shareable-link" aria-label="Permalink to &quot;Via shareable link&quot;">​</a></h3><ol><li>Click the link — if you&#39;re not logged in, sign in or create a hub account</li><li>The shared library is immediately accessible under <strong>&quot;Shared with me&quot;</strong></li></ol><hr><h2 id="_5-managing-shared-access" tabindex="-1">5. Managing Shared Access <a class="header-anchor" href="#_5-managing-shared-access" aria-label="Permalink to &quot;5. Managing Shared Access&quot;">​</a></h2><p>As a library owner, you can manage all active shares from the <strong>Sharing</strong> tab:</p><ul><li><strong>View</strong> all active shares and their permission levels</li><li><strong>Change</strong> a permission level for an existing share</li><li><strong>Revoke</strong> access at any time (immediate effect)</li><li><strong>Set an expiry</strong> on email invites — after the expiry date the link becomes invalid</li></ul><p>As a recipient:</p><ul><li>Shared libraries appear under <strong>&quot;Shared with me&quot;</strong> in your hub dashboard</li><li>You cannot re-share content you have been given access to</li><li>Your access can be revoked by the library owner at any time</li></ul><hr><h2 id="_6-what-can-go-wrong" tabindex="-1">6. What Can Go Wrong <a class="header-anchor" href="#_6-what-can-go-wrong" aria-label="Permalink to &quot;6. What Can Go Wrong&quot;">​</a></h2><h3 id="_1-friend-doesn-t-receive-the-invite-email" tabindex="-1">1. Friend doesn&#39;t receive the invite email <a class="header-anchor" href="#_1-friend-doesn-t-receive-the-invite-email" aria-label="Permalink to &quot;1. Friend doesn&#39;t receive the invite email&quot;">​</a></h3><p><strong>Symptom:</strong> The sender sees &quot;Invite sent&quot; but the recipient cannot find the email.</p><p><strong>Diagnosis:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check the hub audit log for invite events:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;share_invite_sent&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .logs/hub-audit.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -20</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Verify the email address — the most common cause is a typo</span></span></code></pre></div><p><strong>Fix:</strong> Ask the recipient to check their spam/junk folder. If still not found, re-send the invite with a verified email address. For enterprise users, ask their mail admin to allow-list <code>noreply@phlix.app</code>.</p><hr><h3 id="_2-friend-creates-an-account-with-a-different-email-than-invited" tabindex="-1">2. Friend creates an account with a different email than invited <a class="header-anchor" href="#_2-friend-creates-an-account-with-a-different-email-than-invited" aria-label="Permalink to &quot;2. Friend creates an account with a different email than invited&quot;">​</a></h3><p><strong>Symptom:</strong> The invite link is clicked but the library doesn&#39;t appear under &quot;Shared with me&quot; after login.</p><p><strong>Diagnosis:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check the hub audit log for invite acceptance:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;share_invite_accepted&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .logs/hub-audit.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -10</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The log shows the invited email vs. the accepting account email</span></span></code></pre></div><p><strong>Fix:</strong> The invite is tied to the exact email address it was sent to. The friend must use the same email address that received the invite, or the library owner must grant access afresh to the friend&#39;s actual email address via the dashboard or CLI.</p><hr><h3 id="_3-shared-library-appears-empty-or-doesn-t-appear" tabindex="-1">3. Shared library appears empty or doesn&#39;t appear <a class="header-anchor" href="#_3-shared-library-appears-empty-or-doesn-t-appear" aria-label="Permalink to &quot;3. Shared library appears empty or doesn&#39;t appear&quot;">​</a></h3><p><strong>Symptom:</strong> Friend accepts the invite and logs in, but the shared server shows no libraries or an empty library.</p><p><strong>Diagnosis:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On the server, check library scan status:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> library:status</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check if a scan is currently running:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aux</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;media_scanner\\|phlix&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grep</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Manually trigger a full library rescan:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> library:scan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span></span></code></pre></div><p><strong>Fix:</strong> Library sharing requires the library scan to be complete. If a scan is still in progress, wait for it to finish. If no scan is running, trigger one manually. The friend should refresh the hub page after the scan completes and verify the library contents.</p><hr><h3 id="_4-view-only-user-cannot-cast-to-dlna" tabindex="-1">4. View-only user cannot cast to DLNA <a class="header-anchor" href="#_4-view-only-user-cannot-cast-to-dlna" aria-label="Permalink to &quot;4. View-only user cannot cast to DLNA&quot;">​</a></h3><p><strong>Symptom:</strong> Friend logs in, browses the shared library, but pressing <strong>Cast</strong> or <strong>Play To</strong> on a DLNA device does nothing or shows an error.</p><p><strong>Diagnosis:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check the current permission level on the share:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> share:list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> friend@example.com</span></span></code></pre></div><p><strong>Fix:</strong> DLNA casting requires <code>View + Playback + Download</code> permission. Ask the library owner to upgrade your permission level:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> share:grant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> friend@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --library</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Movies&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --permission</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download</span></span></code></pre></div><p>Or via the hub dashboard — change the share&#39;s permission to <strong>&quot;View + Playback + Download&quot;</strong>.</p><hr><h2 id="_7-next-steps" tabindex="-1">7. Next Steps <a class="header-anchor" href="#_7-next-steps" aria-label="Permalink to &quot;7. Next Steps&quot;">​</a></h2><ul><li><a href="./claim-server.html">Claim your server to the hub</a> — connect your server to the hub before you can share libraries</li><li><a href="./what-is-the-hub.html">Hub: what is the hub?</a> — overview of all hub features and account management</li><li><a href="./self-host-the-hub.html">Self-host the hub</a> — run your own hub instance for full control</li><li><a href="./troubleshooting.html">Troubleshooting</a> — if sharing issues persist after trying the fixes above</li></ul>`,62)])])}const g=i(n,[["render",r]]);export{c as __pageData,g as default};
